import math
from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

def serial_convex_hull(points):
    points = sorted(points)
    if len(points) <= 2: return points

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]

@task(returns=list)
def compute_local_hull(pair):
    return serial_convex_hull(pair)

@task(returns=list)
def merge_hulls(hull_a, hull_b):
    combined = hull_a + hull_b
    return serial_convex_hull(combined)

@task(returns=float)
def compute_partial_perimeter(segment):
    dist = 0.0
    for i in range(len(segment) - 1):
        p1 = segment[i]
        p2 = segment[i+1]
        dist += math.hypot(p1[0] - p2[0], p1[1] - p2[1])
    return dist

@task(returns=float)
def add_perimeters(val_a, val_b):
    return val_a + val_b


def main(points):
    pairs = [points[i:i + 2] for i in range(0, len(points), 2)]
    working_list = [compute_local_hull(pair) for pair in pairs]

    while len(working_list) > 1:
        new_level = []
        for i in range(0, len(working_list), 2):
            if i + 1 < len(working_list):
                merged = merge_hulls(working_list[i], working_list[i+1])
                new_level.append(merged)
            else:
                new_level.append(working_list[i])
        working_list = new_level

    final_hull = compss_wait_on(working_list[0])

    if not final_hull or len(final_hull) < 2:
        return final_hull, 0.0

    closed_hull = final_hull + [final_hull[0]]

    segments = []
    for i in range(0, len(closed_hull) - 1, 2):
        end = min(i + 3, len(closed_hull))
        segments.append(closed_hull[i:end])

    partial_dists = [compute_partial_perimeter(seg) for seg in segments]

    while len(partial_dists) > 1:
        new_level = []
        for i in range(0, len(partial_dists), 2):
            if i + 1 < len(partial_dists):
                new_level.append(add_perimeters(partial_dists[i], partial_dists[i+1]))
            else:
                new_level.append(partial_dists[i])
        partial_dists = new_level

    total_perimeter = compss_wait_on(partial_dists[0])

    return total_perimeter
